import { copyToClipboard } from 'quasar';
import { notify } from 'src/components/notifications/notify';

export default {
  methods: {
    copyText(value: string) {
      if (value.trim().length == 0) {
        return;
      }

      copyToClipboard(value).then(() => {
        notify.info('Copied!');
      });
    },
  },
};
